template.script:
(function() {
    // إحداثيات مبدئية (القاهرة افتراضياً)
    var defaultLat = parseFloat(
        document.getElementById('latitude_input').value
    ) || 30.0444;
    var defaultLon = parseFloat(
        document.getElementById('longitude_input').value
    ) || 31.2357;
    var hasLocation = (
        document.getElementById('latitude_input').value
        && parseFloat(document.getElementById('latitude_input').value) !== 0
    );

    // تهيئة الخريطة
    var map = L.map('map_container').setView(
        [defaultLat, defaultLon],
        hasLocation ? 14 : 6
    );

    L.tileLayer(
        'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
        { attribution: '© OpenStreetMap' }
    ).addTo(map);

    // ضع marker لو في إحداثيات محفوظة
    var marker = null;
    if (hasLocation) {
        marker = L.marker([defaultLat, defaultLon]).addTo(map);
    }

    // لما المستخدم يضغط على الخريطة
    map.on('click', function(e) {
        var lat = e.latlng.lat.toFixed(7);
        var lon = e.latlng.lng.toFixed(7);

        // حدّث الـ hidden inputs
        document.getElementById('latitude_input').value  = lat;
        document.getElementById('longitude_input').value = lon;

        // حدّث الـ display inputs
        document.getElementById('lat_display').value = lat;
        document.getElementById('lon_display').value = lon;

        // حرّك الـ marker
        if (marker) {
            map.removeLayer(marker);
        }
        marker = L.marker(e.latlng).addTo(map);
    });
})();
